//! The private browser-network callback used by the compiled `TinyComputer`
//! module. The authenticated host adapter translates these requests to
//! `TinySecurity`'s destination-only browser-dial contract; it must not make
//! policy decisions or resolve destinations itself.
//!
//! The module owns browser proxy parsing, exact approved-address dialing, and
//! live-lease enforcement. These callbacks carry only destination authority,
//! opaque `TinySecurity` grants, and a session ID generated by the module. They
//! never carry browser methods, headers, body bytes, or page/model claims.

mod types;
pub use types::{
    BrowserEgressConsumeRequest, BrowserEgressDecision, BrowserEgressGrant, BrowserEgressTarget,
    BrowserEgressValidateRequest,
};

/// Host interface implemented by an authenticated adapter to `TinySecurity`.
pub const INTERFACE: &str = "ai.tinyhumans.tinycomputer.BrowserEgressHost";
/// Object path for [`INTERFACE`].
pub const OBJECT_PATH: &str = "/ai/tinyhumans/tinycomputer/BrowserEgressHost";

/// Callback member names.
pub mod methods {
    /// Ask `TinySecurity` to resolve and authorize the actual browser destination.
    pub const AUTHORIZE: &str = "Authorize";
    /// Consume a one-use `TinySecurity` grant before the socket dial.
    pub const CONSUME: &str = "Consume";
    /// Validate an active HTTPS or WebSocket tunnel lease.
    pub const VALIDATE: &str = "Validate";
}

/// Callback names in dispatch order.
pub const METHODS: [&str; 3] = [methods::AUTHORIZE, methods::CONSUME, methods::VALIDATE];

